import itertools

# Re-define the function scope to ensure memo is clear or available in the new environment
memo = {}

def get_subnumbers(m):
    s = str(m)
    subnumbers = []
    for i in range(len(s)):
        sub = s[:i] + s[i+1:]
        if sub:
            subnumbers.append(int(sub))
    return subnumbers

def is_good(m):
    if m in memo:
        return memo[m]

    s_m = str(m)

    # Constraint check: Distinct nonzero digits
    if len(set(s_m)) != len(s_m) or any(c == '0' for c in s_m):
        return False

    # Base Case 1: Single-digit number
    if len(s_m) == 1:
        memo[m] = True
        return True

    # Recursive step
    subnumbers = get_subnumbers(m)

    for d in subnumbers:
        # Condition 1: d is a divisor of m
        # Condition 2: d is a good number
        if m % d == 0 and is_good(d):
            memo[m] = True
            return True

    memo[m] = False
    return False


def find_largest_good():
    digits = [1, 2, 3, 4, 5, 6, 7, 8, 9]

    # We iterate from the longest possible number (9 digits) down to 2 digits.
    # Permutations are generated in lexicographical order by default, so we need a custom way 
    # to ensure descending order for the search to stop immediately at the largest.

    # Generate all permutations of digits
    all_perms = []
    for k in range(9, 1, -1):
        for p in itertools.permutations(digits, k):
            all_perms.append(p)

    # Sort all permutations numerically in descending order
    all_perms.sort(key=lambda p: int("".join(map(str, p))), reverse=True)

    for p in all_perms:
        m = int("".join(map(str, p)))
        if is_good(m):
            return m
    return 9 # Should not happen

print(f"The largest good number found is: {find_largest_good()}")

